 ArrayList<org.json.JSONObject> records(){ArrayList<org.json.JSONObject> a=new ArrayList<>();for(Object v:getSharedPreferences("tests",0).getAll().values())try{a.add(new org.json.JSONObject(v.toString()));}catch(Exception ignored){}return a;}
