 void findAsset(String id){org.json.JSONObject best=null;for(org.json.JSONObject o:lookupRecords())if(sameCustomer(o)&&o.optString("asset").equalsIgnoreCase(id)&&(best==null||o.optString("created",o.optString("date")).compareTo(best.optString("created",best.optString("date")))>0))best=o;if(best==null){status.setText("Asset not found for selected customer.");return;}asset.setText(best.optString("asset"));description.setText(best.optString("description"));selectResult(0);interval.setSelection(0);String months=best.optString("months");for(int i=1;i<interval.getCount();i++)if(months.equals(interval.getItemAtPosition(i).toString()))interval.setSelection(i);fault.setText("");existing=true;entry.setVisibility(View.VISIBLE);status.setText("Existing asset loaded. Perform and confirm new test.");}

