 String clean(String s){return s.replaceAll("[^A-Za-z0-9 ._-]","");}
 void generate(){pendingId=null;try{int w=(int)Math.round(Double.parseDouble(width.getText().toString())*8),h=(int)Math.round(Double.parseDouble(length.getText().toString())*8);if(w<160||w>432||h<240||h>16000)throw new IllegalArgumentException();String name=clean(heading.getText().toString()),id=clean(asset.getText().toString());if(name.length()>18||id.length()>12||id.isEmpty())throw new IllegalArgumentException();command.setText("^XA\n^PW"+w+"\n^LL"+h+"\n^LH0,0\n^FO16,32^A0N,30,25^FD"+name+"^FS\n^FO16,76^GB"+(w-32)+",3,3^FS\n^FO16,100^A0N,22,18^FDSAMPLE ONLY^FS\n^FO16,132^A0N,20,16^FDNOT A TEST RECORD^FS\n^FO16,170^A0N,20,16^FDTested by: "+(users.getSelectedItemPosition()>0?userInitials.get(users.getSelectedItemPosition()-1):"NOT SELECTED")+"^FS\n^FO16,205^BY1^BCN,48,Y,N,N^FD"+id+"^FS\n^PQ1^XZ");}catch(Exception e){status.setText("Check dimensions (20–54 mm wide, 30–2000 mm long) and sample text lengths.");}}
 String labelText(String s){return s.replaceAll("[^A-Za-z0-9 ._/-]","");}
 void saveTest(){if(!print.isEnabled())return;int u=users.getSelectedItemPosition(),res=selectedResult;String id=asset.getText().toString().trim();if(u<=0||res==0||!id.matches("[A-Za-z0-9_-]{1,12}")||customer.getText().toString().trim().isEmpty()||site.getText().toString().trim().isEmpty()||description.getText().toString().trim().isEmpty()||(res==1&&interval.getSelectedItemPosition()==0)||(res==2&&fault.getText().toString().trim().isEmpty())){status.setText("Complete customer, site, asset, description, tester, result and interval or failure details.");return;}
 if(res==2){new AlertDialog.Builder(this).setTitle("Failed equipment").setMessage("Remove equipment from service and attach a failed equipment warning. Confirm the recorded result.").setNegativeButton("Cancel",null).setPositiveButton("Confirm failure",(d,i)->recordTest()).show();}else new AlertDialog.Builder(this).setTitle("Confirm PASS").setMessage("Confirm all required inspections and electrical tests have passed.").setNegativeButton("Cancel",null).setPositiveButton("Confirm",(d,i)->recordTest()).show();}
 void recordTest(){try{int u=users.getSelectedItemPosition()-1;boolean pass=selectedResult==1;java.time.LocalDate today=java.time.LocalDate.now();String due=pass?today.plusMonths(Integer.parseInt(interval.getSelectedItem().toString())).toString():"";String id=asset.getText().toString();String initials=userInitials.get(u);String z="^XA\n^PW352^LL784^LH0,0\n^FO16,24^A0N,32,26^FDELEC.TECH^FS\n^FO16,70^GB320,3,3^FS\n^FO16,88^A0N,28,17^FD"+(pass?"TESTED & PASSED":"FAILED - DO NOT USE")+"^FS\n^FO16,132^A0N,23,20^FDTested: "+today+"^FS\n^FO16,166^A0N,23,20^FD"+(pass?"Due: "+due:"REMOVE FROM SERVICE")+"^FS\n^FO16,200^A0N,23,20^FDTested by: "+initials+"^FS\n^FO16,234^A0N,20,18^FDAS/NZS 3760^FS\n^FO16,270^BY2^BCN,60,Y,N,N^FD"+id+"^FS\n^FO330,650^A0I,36,24^FDELEC.TECH^FS\n^PQ1^XZ";
 org.json.JSONObject o=new org.json.JSONObject();String key=UUID.randomUUID().toString();o.put("id",key);o.put("created",java.time.Instant.now().toString());o.put("months",pass?interval.getSelectedItem().toString():"");o.put("asset",id);o.put("customer",customer.getText().toString());o.put("site",site.getText().toString());o.put("description",description.getText().toString());o.put("tester",userNames.get(u));o.put("initials",initials);o.put("date",today.toString());o.put("due",due);o.put("result",pass?"PASS":"FAIL");o.put("fault",pass?"":fault.getText().toString());o.put("zpl",z);o.put("printState","Pending");if(!getSharedPreferences("tests",0).edit().putString(key,o.toString()).commit())throw new java.io.IOException("Storage failed");pendingId=key;command.setText(z);entry.setVisibility(View.GONE);send();syncNow();}catch(Exception e){status.setText("Unable to save test: "+e.getMessage());}}
 void history(){ArrayList<String> keys=new ArrayList<>(),labels=new ArrayList<>();for(java.util.Map.Entry<String,?> e:getSharedPreferences("tests",0).getAll().entrySet())try{org.json.JSONObject o=new org.json.JSONObject(e.getValue().toString());keys.add(e.getKey());labels.add(o.getString("date")+" | "+o.getString("asset")+" | "+o.getString("result")+" | "+o.optString("printState"));}catch(Exception ignored){}if(keys.isEmpty()){status.setText("No saved tests");return;}new AlertDialog.Builder(this).setTitle("Saved tests — select to load tag").setItems(labels.toArray(new String[0]),(d,i)->{try{pendingId=keys.get(i);command.setText(new org.json.JSONObject(getSharedPreferences("tests",0).getString(pendingId,"{}")).getString("zpl"));new AlertDialog.Builder(this).setTitle("Reprint saved tag?").setMessage("Check whether the original printed before retrying.").setNegativeButton("Cancel",null).setPositiveButton("Reprint",(x,y)->send()).show();}catch(Exception ignored){}}).show();}
 void markPrinted(String key){if(key==null)return;new AlertDialog.Builder(this).setTitle("Did the physical tag print?").setNegativeButton("No / uncertain",(d,i)->setPrintState(key,"Pending / uncertain")).setPositiveButton("Yes",(d,i)->setPrintState(key,"Confirmed printed")).show();}
